import {STORAGE_KEY,SEVERITY,STATUS,KIND,USAGE,RISK,OUTCOME,blank,active,repoOf,alertOf,repoName,sharedGroups,urgency,blocked,readiness,roadmap,quality,validateRepo,validateAlert,validatePlan,validateClosure,validateBackup,normalizeDependabot,importPreview,csvCell,validGithubUrl,validHttps,demoDataset} from './core.js';
import {icon as I} from './icons.js';

/** Didban's UI has no automatic remote actions. All changes stay in localStorage. */
const ONBOARD_KEY='didban-en-onboarded-v1';
const THEME_KEY='didban-en-theme-v1';
const pages=[
 ['overview','layout-dashboard','Overview'],['alerts','shield-alert','Alerts'],['repositories','layers','Repositories'],
 ['shared','git-branch','Shared dependencies'],['roadmap','list-ordered','Remediation roadmap'],
 ['insights','eye','Quality & follow-up'],['guide','info','How it works'],['settings','settings','Settings']
];
const state={page:'overview',selected:'',tab:'summary',modal:'',modalId:'',modalTest:'',modalMethod:'',toast:'',drawer:false,theme:localStorage.getItem(THEME_KEY)||'light',
 filters:{q:'',severity:'',status:'',repositoryId:'',codeUse:'',sort:'urgency',quick:'all'},onboardStep:0,staged:null,commandQuery:''};
function load(){try{const raw=JSON.parse(localStorage.getItem(STORAGE_KEY));return validateBackup(raw);}catch{return blank();}}
let data=load();
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(data));return true;}catch{toast('Could not save to browser storage. Export a backup before leaving.',true);return false;}}
const uid=()=>crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2);
const now=()=>new Date().toISOString();
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>Number(n||0).toLocaleString('en-US');
const dt=v=>{if(!v)return 'Not recorded';const d=new Date(v);return Number.isNaN(+d)?'Invalid date':new Intl.DateTimeFormat('en-US',{year:'numeric',month:'short',day:'numeric'}).format(d);};
const show=v=>v===null||v===undefined||String(v).trim()===''?'<span class="muted">Not recorded</span>':esc(v);
const pill=(label,kind='unknown')=>`<span class="pill ${esc(kind)}">${esc(label)}</span>`;
const severityBadge=a=>pill(SEVERITY[a.severity]||'Unverified',a.severity);
const statusBadge=a=>pill(STATUS[a.status]||'Unknown',a.status);
const button=(label,action,mode='primary',id='',ico='plus')=>`<button type="button" class="btn ${esc(mode)}" data-action="${esc(action)}" ${id?`data-id="${esc(id)}"`:''}>${I(ico,15)} ${esc(label)}</button>`;
const link=(url,text)=>url&&(validGithubUrl(url)||validHttps(url))?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(text)} ↗</a>`:'<span class="muted">Not provided</span>';
function toast(message,isError=false){document.querySelector('.toast')?.remove();const n=document.createElement('div');n.className='toast'+(isError?' error':'');n.setAttribute('role',isError?'alert':'status');n.textContent=message;document.body.appendChild(n);setTimeout(()=>n.remove(),3900);}
function log(alertId,action,details){data.history.unshift({id:uid(),alertId,action,detail:details,at:now()});}
function navigate(page,id=''){state.page=page;state.selected=id;state.tab='summary';state.modal='';state.drawer=false;render();window.scrollTo(0,0);}
function modal(type,id='',test='',method=''){state.modal=type;state.modalId=id;state.modalTest=test;state.modalMethod=method;render();requestAnimationFrame(()=>document.querySelector('.dialog-new [autofocus],.dialog-new input,.dialog-new button')?.focus());}
const head=(eyebrow,title,description='',actions='')=>`<div class="page-head"><div><div class="eyebrow">${esc(eyebrow)}</div><h1 class="page-title">${esc(title)}</h1>${description?`<p class="subtitle">${esc(description)}</p>`:''}</div><div class="actions">${actions}</div></div>`;
const stat=(title,num,caption,ico,kind='')=>`<article class="stat"><div class="stat-top"><span>${esc(title)}</span><span class="stat-icon ${kind}">${I(ico,19)}</span></div><div class="stat-val">${fmt(num)}</div><div class="stat-note">${esc(caption)}</div></article>`;
const empty=(ico,title,description='',action='')=>`<div class="empty"><div class="empty-icon">${I(ico,26)}</div><strong>${esc(title)}</strong><div class="small">${esc(description)}</div>${action}</div>`;
const panel=(title,sub,body,action='')=>`<section class="panel"><div class="panel-head"><div><h2 class="panel-title">${esc(title)}</h2>${sub?`<div class="panel-sub">${esc(sub)}</div>`:''}</div>${action}</div><div class="panel-body">${body}</div></section>`;
const box=(label,val)=>`<div class="info-box"><div class="info-label">${esc(label)}</div><div class="info-value">${val}</div></div>`;
const rowAction=(title,description,page,ico)=>`<button type="button" data-action="nav" data-page="${page}" class="quick-action"><span class="quick-action-ico">${I(ico,19)}</span><span class="item-main"><strong>${esc(title)}</strong><small>${esc(description)}</small></span><span class="arr">${I('arrow',16)}</span></button>`;
function shell(content){
 const current=state.page==='detail'?'alerts':state.page;
 const navItems=pages.map(([key,ico,label])=>`<button type="button" data-action="nav" data-page="${key}" class="${current===key?'active':''}" ${current===key?'aria-current="page"':''}>${I(ico)}<span>${esc(label)}</span></button>`).join('');
 const mobile=pages.filter(([key])=>['overview','alerts','repositories','roadmap'].includes(key));
 const title=pages.find(([key])=>key===current)?.[2]||'Alert details';
 return `<div class="app-shell"><aside class="sidebar" aria-label="Primary navigation"><div class="brand"><span class="brand-mark">${I('shield',27)}</span><div><div class="brand-title">Didban Security</div><div class="brand-sub">DEPENDENCY OPERATIONS</div></div></div>
 <div class="nav-label">WORKSPACE</div><nav class="nav">${navItems}</nav>
 <div class="sidebar-bottom"><div class="sidebar-status"><div class="status-overline"><span class="status-dot"></span> Local-first · No GitHub write access</div><p>Your records stay in this browser. Upgrade commands are documentation only and are never executed.</p></div><div class="sidebar-foot"><span>Open source edition</span><span>v1.0</span></div></div></aside>
 <main class="main" id="main-content"><header class="topbar"><div class="breadcrumb"><span class="breadcrumb-root">Workspace</span><span class="breadcrumb-sep">/</span><strong style="color:var(--ink)">${esc(title)}</strong></div><div class="top-actions"><span class="top-local"><i></i> Browser storage</span><button class="btn sm header-help" data-action="nav" data-page="guide">${I('info',15)} Getting started</button><button type="button" class="icon-btn" aria-label="Search or navigate (Ctrl+K)" title="Search (Ctrl+K)" data-action="palette">${I('search')}</button><button type="button" class="icon-btn" aria-label="Toggle dark mode" title="Toggle dark mode" data-action="theme">${I(state.theme==='dark'?'sun':'moon')}</button><button type="button" class="btn primary sm" data-action="new-alert">${I('plus',15)} New alert</button></div></header>
 <div class="content">${content}<div class="footnote">A local-first security planning workspace · All facts come from your records · Validate changes and tests before releasing</div></div></main></div>
 <nav class="mobile-nav" aria-label="Mobile navigation">${mobile.map(([key,ico,label])=>`<button class="${current===key?'active':''}" data-action="nav" data-page="${key}">${I(ico)}<span>${esc(label==='Remediation roadmap'?'Roadmap':label)}</span></button>`).join('')}<button class="${['shared','insights','guide','settings'].includes(current)?'active':''}" data-action="drawer" aria-label="More pages">${I('menu')}<span>More</span></button></nav>
 ${state.drawer?`<div class="drawer-backdrop" data-action="drawer-close"></div><div class="mobile-drawer" role="dialog" aria-modal="true" aria-label="More pages"><div class="mobile-drawer-head"><strong>Explore Didban</strong><button class="icon-btn" aria-label="Close menu" data-action="drawer-close">${I('menu')}</button></div><div class="drawer-nav">${pages.map(([key,ico,label])=>`<button data-action="nav" data-page="${key}" class="${key===current?'active':''}">${I(ico)} ${esc(label)}</button>`).join('')}</div></div>`:''}
 ${state.modal?modalView():''}`;
}
function render(){document.documentElement.dataset.theme=state.theme;document.getElementById('app').innerHTML=shell(({overview:overviewPage,alerts:alertsPage,repositories:repositoriesPage,shared:sharedPage,roadmap:roadmapPage,insights:insightsPage,guide:guidePage,settings:settingsPage,detail:detailPage}[state.page]||overviewPage)());}
function getNextAction(){
 const r=roadmap(data),open=active(data);
 if(!data.repositories.length)return {title:'Start with your first repository',text:'Add an actual GitHub repository before tracking dependency alerts.',button:button('Add repository','repo-new'),info:'A repository is a reference only—no permissions or tokens required.'};
 if(!data.alerts.length)return {title:'Record your first security alert',text:'Log the exact package, advisory, impact and remediation versions.',button:button('Add security alert','new-alert'),info:'Start from a verified GitHub Dependabot alert.'};
 const missing=quality(data);
 if(missing.length)return {title:'Complete missing evidence',text:`${missing.length} open alert${missing.length===1?'':'s'} need stronger facts or ownership before execution.`,button:button('Review data quality','nav-insights'),info:'Unknown values are deliberately never estimated.'};
 if(r.blocked.length)return {title:'Unblock failing work',text:`${r.blocked.length} alert${r.blocked.length===1?'':'s'} have a blocker or failed test.`,button:button('See remediation blockers','nav-roadmap'),info:'A failed check prevents an item from entering the ready queue.'};
 if(r.incomplete.length)return {title:'Prepare your remediation plan',text:'Confirm commands, compatibility, rollback and regression checks.',button:button('Open roadmap','nav-roadmap'),info:'Nothing is executed automatically.'};
 if(r.ready.length)return {title:'Review the ready queue',text:`${r.ready.length} item${r.ready.length===1?'':'s'} have documented prerequisites for manual execution.`,button:button('Review upgrade order','nav-roadmap'),info:'Approval is not a substitute for actual testing.'};
 return {title:'All tracked alerts are closed',text:'Review history, export evidence, or capture a new advisory.',button:button('View activity','nav-settings'),info:'Keep backups outside this browser.'};
}
function overviewPage(){
 const open=active(data),q=roadmap(data),missing=quality(data),next=getNextAction();
 const counts=Object.keys(SEVERITY).map(k=>({key:k,count:open.filter(a=>a.severity===k).length}));
 const urgent=open.filter(a=>a.severity==='high'||a.severity==='critical').length;
 const top=[...open].sort((a,b)=>urgency(data,b).score-urgency(data,a).score).slice(0,5);
 const hero=`<section class="hero"><div><div class="hero-kicker"><span class="status-dot"></span> SECURITY OPERATIONS / DEPENDENCY RISK</div><h2>${data.repositories.length?'Turn vulnerability signals into confident decisions.':'Make your dependency risk manageable.'}</h2><p>Prioritize with evidence, document upgrade steps, track verification, and maintain a clear record. Every decision stays under human control.</p><div class="hero-buttons">${button(data.repositories.length?'Review alerts':'Add your first repository',data.repositories.length?'nav-alerts':'repo-new')}${button('Explore the workflow','nav-guide','ghost','','info')}</div></div><div class="hero-side"><div class="hero-metric"><span>Open alerts</span><strong>${fmt(open.length)}</strong></div><div class="hero-metric"><span>Ready for action</span><strong class="emphasis">${fmt(q.ready.length)}</strong></div><p class="hero-note">Live local records · No fabricated security data</p></div></section>`;
 const nextHTML=`<div class="triage-banner"><div><div class="triage-label">RECOMMENDED NEXT STEP</div><h2 class="triage-title">${esc(next.title)}</h2><p class="triage-desc">${esc(next.text)} <span class="muted">${esc(next.info)}</span></p></div><div class="actions">${next.button}</div></div>`;
 const onb= !data.repositories.length?`<section class="onboard"><div><div class="onboard-title">Your path to a defensible fix ${button('Take the tour','welcome','sm','','info')}</div><div class="onboard-sub">Three steps to turn GitHub alerts into auditable remediation decisions.</div></div><div class="onboard-steps"><div class="onboard-step"><div class="step-num">1</div><div><strong>Register a repository</strong><span>Provide its verified GitHub URL</span></div></div><div class="onboard-step"><div class="step-num">2</div><div><strong>Triage actual alerts</strong><span>Capture severity, versions and evidence</span></div></div><div class="onboard-step"><div class="step-num">3</div><div><strong>Plan, test and close</strong><span>Record commands, rollback and outcomes</span></div></div></div></section>`:'';
 const topBody=top.length?top.map(a=>`<div class="row-item"><div class="stat-icon ${['critical','high'].includes(a.severity)?'red':''}">${I('package',19)}</div><div class="item-main"><div class="item-title">${esc(a.packageName)}</div><div class="item-sub">${esc(repoName(data,a))} · ${urgency(data,a).needsReview?'Needs evidence':'Priority score '+urgency(data,a).score}</div></div><div class="item-end">${severityBadge(a)}<button class="icon-btn" data-action="detail" data-id="${esc(a.id)}" aria-label="View alert">${I('arrow',16)}</button></div></div>`).join(''):empty('shield','No active alerts yet','Record a real alert or import a Dependabot JSON file.',button('Add alert','new-alert'));
 const sevBody=open.length?`<div class="analytics-list">${counts.map(({key,count})=>`<div class="analytics-row"><span style="min-width:94px">${SEVERITY[key]}</span><div class="analytics-bar"><span style="width:${open.length?count/open.length*100:0}%;background:${({critical:'#dc5775',high:'#ef9266',moderate:'#efba60',low:'#27af9a',unknown:'#9babc3'})[key]}"></span></div><strong>${fmt(count)}</strong></div>`).join('')}</div>`:empty('info','Nothing to chart','Severity distribution appears after you record real data.');
 const paths=`<div class="quick-actions">${rowAction('Triage high-risk alerts',`${urgent} critical or high severity items`,'alerts','shield-alert')}${rowAction('Build the remediation queue',`${q.ready.length} ready · ${q.blocked.length} blocked`,'roadmap','list-ordered')}${rowAction('Inspect shared dependencies',`${sharedGroups(data).length} packages across repositories`,'shared','git-branch')}${rowAction('Complete evidence gaps',`${missing.length} alerts need follow-up`,'insights','eye')}</div>`;
 return `${head('OVERVIEW · COMMAND CENTER','Dependency risk at a glance','From unverified alerts to documented and testable remediation.',button('Add repository','repo-new'))}${hero}${onb}${nextHTML}<div class="stats-grid">${stat('Tracked repositories',data.repositories.length,'Repository references only','layers')}${stat('Open alerts',open.length,'Excludes closed alerts','shield-alert','red')}${stat('High / critical',urgent,'Based on recorded severity','alert','amber')}${stat('Ready for remediation',q.ready.length,'Approval prerequisites completed','check','teal')}</div><div class="two-col">${panel('Highest-priority alerts','Evidence-weighted urgency · not a vulnerability severity score',topBody,`<button class="action-link" data-action="nav" data-page="alerts">View all ${I('arrow',15)}</button>`)}${panel('Execution readiness','Open items grouped by the next operational decision',`<div class="analytics-list">${[['Ready',q.ready.length,'ready'],['Blocked',q.blocked.length,'blocked'],['Incomplete',q.incomplete.length,'review'],['Closed',q.closed.length,'resolved']].map(([label,n,kind])=>`<div class="kpi-section"><span>${pill(label,kind)}</span><strong class="mini-count">${fmt(n)}</strong></div>`).join('')}</div>`)}</div><div class="two-col">${panel('Open alert severity','Values are taken only from the alerts you entered',sevBody)}${panel('Your workflow','Jump directly to an actionable next step',paths)}</div>`;
}
function filteredAlerts(){
 const f=state.filters,q=f.q.trim().toLowerCase();
 const list=data.alerts.filter(a=>(!q||[a.packageName,a.alertId,a.currentVersion,a.safeVersion,a.depPath,a.notes,a.owner,repoName(data,a)].some(x=>String(x||'').toLowerCase().includes(q)))&&(!f.severity||f.severity===a.severity)&&(!f.status||f.status===a.status)&&(!f.repositoryId||f.repositoryId===a.repositoryId)&&(!f.codeUse||f.codeUse===a.codeUse)
 &&(f.quick==='all'||(f.quick==='urgent'&&['critical','high'].includes(a.severity))||(f.quick==='evidence'&&urgency(data,a).needsReview)||(f.quick==='ready'&&readiness(a).ready)||(f.quick==='blocked'&&blocked(a))));
 list.sort((a,b)=>f.sort==='updated'?new Date(b.updatedAt||b.createdAt)-new Date(a.updatedAt||a.createdAt):f.sort==='package'?String(a.packageName).localeCompare(String(b.packageName)):f.sort==='severity'?({critical:4,high:3,moderate:2,low:1}[b.severity]||0)-({critical:4,high:3,moderate:2,low:1}[a.severity]||0):urgency(data,b).score-urgency(data,a).score);
 return list;
}
const opts=(mapping,current,placeholder='All')=>`<option value="">${esc(placeholder)}</option>`+Object.entries(mapping).map(([key,val])=>`<option value="${esc(key)}" ${key===current?'selected':''}>${esc(val)}</option>`).join('');
function alertsPage(){
 const f=state.filters,found=filteredAlerts();
 const quick=[['all','All alerts'],['urgent','High impact'],['evidence','Needs evidence'],['blocked','Blocked'],['ready','Ready']].map(([v,label])=>`<button type="button" class="filter-chip ${f.quick===v?'active':''}" data-action="quick" data-value="${v}">${label}</button>`).join('');
 const filters=`<div class="toolbar"><input id="search-alerts" aria-label="Search alerts" class="field search" placeholder="Search packages, owners, alert IDs, versions…" value="${esc(f.q)}"><select class="filter-select" data-filter="severity" aria-label="Severity">${opts(SEVERITY,f.severity,'All severities')}</select><select class="filter-select" data-filter="status" aria-label="Status">${opts(STATUS,f.status,'All statuses')}</select><select class="filter-select" data-filter="repositoryId" aria-label="Repository">${opts(Object.fromEntries(data.repositories.map(r=>[r.id,r.alias||r.slug])),f.repositoryId,'All repositories')}</select><select class="filter-select" data-filter="codeUse" aria-label="Code usage">${opts(USAGE,f.codeUse,'Code usage')}</select><select class="filter-select" data-filter="sort" aria-label="Sort alerts">${Object.entries({urgency:'Priority score',updated:'Recently changed',severity:'Severity',package:'Package A–Z'}).map(([v,t])=>`<option value="${v}" ${f.sort===v?'selected':''}>${t}</option>`).join('')}</select>${button('Clear filters','filters-reset','sm','','filter')}</div>`;
 const mobileCards=found.map(a=>{const u=urgency(data,a);return `<article class="mobile-alert-card"><div class="mobile-alert-top"><div><div class="mobile-alert-package">${esc(a.packageName)}</div><div class="small muted">${esc(repoName(data,a))} · ${esc(a.alertId||'No ID')}</div></div>${severityBadge(a)}</div><div class="mobile-alert-facts"><span>Priority <strong>${u.score}</strong></span><span>${statusBadge(a)}</span></div><div class="mobile-alert-facts"><span>Safe version: <strong>${esc(a.safeVersion||'Unverified')}</strong></span><span>${esc(a.owner||'Unassigned')}</span></div><button class="btn sm" data-action="detail" data-id="${esc(a.id)}">Review alert ${I('arrow',14)}</button></article>`;}).join('');
 const rows=found.map(a=>{const u=urgency(data,a);return `<tr data-action="detail" data-id="${esc(a.id)}" tabindex="0" role="button" aria-label="View ${esc(a.packageName)} alert"><td><div class="pkg">${esc(a.packageName)}</div><div class="small muted">${esc(a.alertId||'No alert ID')}</div></td><td>${esc(repoName(data,a))}</td><td>${severityBadge(a)}</td><td><strong>${u.score}</strong> ${u.needsReview?pill('Needs review','review'):''}</td><td>${statusBadge(a)}</td><td>${a.safeVersion?`<code>${esc(a.safeVersion)}</code>`:'<span class="muted">Unknown</span>'}</td><td>${esc(a.owner||'Unassigned')}</td><td>${I('arrow',16)}</td></tr>`;}).join('');
 return `${head('VULNERABILITY TRIAGE','Security alerts','Inspect each package, validate evidence, assign ownership, and build an accurate remediation plan.',`${button('Import Dependabot JSON','dependabot-open','sm','','file')}${button('New alert','new-alert')}`)}<div class="quick-tags">${quick}</div><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Alert register <span class="count">${fmt(found.length)} / ${fmt(data.alerts.length)}</span></h2><div class="panel-sub">The priority score helps sort work. It does not replace advisory severity or real exploitability analysis.</div></div></div><div class="panel-body">${filters}${found.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Package / ID</th><th>Repository</th><th>Severity</th><th>Priority</th><th>Status</th><th>Safe version</th><th>Owner</th><th></th></tr></thead><tbody>${rows}</tbody></table></div><div class="mobile-alert-list">${mobileCards}</div>`:empty('search','No alerts match your view','Try resetting filters or capture a real Dependabot alert.',button('Reset filters','filters-reset','sm','','filter'))}</div></section>`;
}
function repositoriesPage(){
 const cards=data.repositories.map(r=>{const alerts=data.alerts.filter(a=>a.repositoryId===r.id),open=alerts.filter(a=>!['resolved','accepted'].includes(a.status)),critical=open.filter(a=>['critical','high'].includes(a.severity));return `<article class="repo-card"><div class="repo-card-head"><div class="repo-icon">${I('layers',21)}</div>${button('Edit','repo-edit','sm',r.id,'edit')}</div><div class="repo-name">${esc(r.alias||r.slug)}</div><div class="small muted">${esc(r.slug)}</div><div class="small" style="margin-top:10px">${link(r.url,'View repository on GitHub')}</div><div class="repo-kpis"><div class="repo-kpi"><strong>${fmt(open.length)}</strong><div>Open alerts</div></div><div class="repo-kpi"><strong>${fmt(critical.length)}</strong><div>High / critical</div></div><div class="repo-kpi"><strong>${fmt(alerts.length)}</strong><div>Tracked</div></div></div><div class="action-menu">${button('Add alert','new-alert','sm',r.id,'plus')}<button class="btn sm" data-action="repo-remove" data-id="${esc(r.id)}">${I('trash',15)} Remove</button></div></article>`;}).join('');
 return `${head('REPOSITORY INVENTORY','Your repositories','Organize alert evidence by repository. Adding a repository here does not grant GitHub access.',button('Add repository','repo-new'))}${data.repositories.length?`<div class="repo-grid">${cards}</div>`:panel('No repositories yet','Start with the owner/repository slug and matching GitHub URL.',empty('layers','Build your inventory','Register a public or private GitHub repository reference. Never provide credentials.',button('Add first repository','repo-new')))}`;
}
function sharedPage(){
 const shared=sharedGroups(data);
 const cards=shared.map(g=>{
   const open=g.alerts.filter(a=>!['resolved','accepted'].includes(a.status));
   return `<article class="repo-card"><div class="repo-card-head"><span class="repo-icon">${I('git-branch',20)}</span>${pill(`${g.repos.size} repositories`,'new')}</div><h2 class="repo-name">${esc(g.name)}</h2><p class="small muted">Ecosystem: ${esc(g.ecosystem)} · ${g.alerts.length} recorded advisories</p><div class="action-menu" style="display:block">${g.alerts.map(a=>`<button class="quick-action" data-action="detail" data-id="${esc(a.id)}" style="width:100%;margin:5px 0;padding:10px"><span class="item-main"><strong>${esc(repoName(data,a))}</strong><small>${esc(a.alertId||'No ID')} · ${esc(STATUS[a.status]||'Unknown')}</small></span>${severityBadge(a)}</button>`).join('')}</div><div class="note" style="margin-top:14px">${I('info',15)} Review once for strategy, but verify and test each repository separately. Nothing is automatically synchronized.</div></article>`;
 }).join('');
 return `${head('CROSS-REPOSITORY ANALYSIS','Shared dependencies','Identify packages appearing in multiple repositories, with scoped remediation per repository.',button('Review alerts','nav-alerts','sm','','shield-alert'))}${shared.length?`<div class="repo-grid">${cards}</div>`:panel('No shared packages found','Shared means the same ecosystem and package name appear in two or more distinct registered repositories.',empty('git-branch','No cross-repository overlap','Add alerts with matching package names in separate repositories to expose overlap.'))}`;
}
function roadmapCard(a,index,group){
 const r=readiness(a),u=urgency(data,a);return `<div class="row-item"><div class="stat-icon ${group==='blocked'?'red':group==='ready'?'teal':''}">${I(group==='ready'?'check':group==='blocked'?'alert':'package',18)}</div><div class="item-main"><div class="item-title">${esc(a.packageName)} <span class="muted">· ${esc(repoName(data,a))}</span></div><div class="item-sub">${esc(a.alertId||'No advisory ID')} · ${esc(RISK[a.plan?.compatRisk||'unknown'])} compatibility risk · Priority ${u.score}</div>${group==='incomplete'?`<div class="small muted">${r.reasons.slice(0,2).map(esc).join(' · ')}</div>`:''}${group==='blocked'?`<div class="small text-danger">${esc(a.blocker||'Failed or blocked test')}</div>`:''}</div><div class="item-end">${severityBadge(a)}${group==='ready'?`<button class="icon-btn" aria-label="Move up" data-action="move-up" data-id="${esc(a.id)}" ${index===0?'disabled':''}>${I('arrow',14)}</button><button class="icon-btn" aria-label="Move down" data-action="move-down" data-id="${esc(a.id)}">${I('arrow',14)}</button>`:''}<button class="icon-btn" data-action="detail" data-id="${esc(a.id)}" aria-label="Open alert details">${I('eye',16)}</button></div></div>`;
}
function roadmapPage(){
 const r=roadmap(data);
 const section=(title,sub,list,group)=>panel(title,sub,list.length?list.map((a,i)=>roadmapCard(a,i,group)).join(''):empty('check',group==='ready'?'Nothing approved for the ready queue':group==='blocked'?'No blockers recorded':group==='incomplete'?'No incomplete plans':'No closed alerts',group==='ready'?'Document commands, risk, rollback, and tests to qualify.':'Items appear here once their state matches the section.'));
 return `${head('REMEDIATION OPERATIONS','Upgrade execution roadmap','A risk-aware manual workflow: document → approve → execute outside Didban → test → close.',button('Review alert register','nav-alerts','sm','','shield-alert'))}<div class="note warn" style="margin-bottom:19px">${I('info',18)} Readiness means documentation is complete, <strong>not</strong> that an upgrade command ran or is safe to execute. Commands are copied, never run by this website.</div><div class="stats-grid">${stat('Ready',r.ready.length,'Approved prerequisites','check','teal')}${stat('Blocked',r.blocked.length,'Recorded blockers / failed checks','alert','red')}${stat('Incomplete',r.incomplete.length,'Missing evidence or plan details','eye','amber')}${stat('Closed',r.closed.length,'Resolved or accepted risk','shield')}</div><div style="display:grid;gap:19px">${section('01 · Ready for manual execution','Ordered by manual position, compatibility risk, then urgency. Use arrows to adjust.',r.ready,'ready')}${section('02 · Blocked','Includes an explicit blocker or any failed / blocked test.',r.blocked,'blocked')}${section('03 · Needs preparation','At least one readiness requirement is missing.',r.incomplete,'incomplete')}${section('04 · Closed work','All resolved and risk-accepted alerts, retained for audit history.',r.closed,'closed')}</div>`;
}
function insightsPage(){
 const flagged=quality(data),open=active(data),total=open.length,blockedCount=open.filter(blocked).length;
 const gapsCount=flagged.reduce((n,x)=>n+x.gaps.length,0);
 return `${head('DATA TRUST · FOLLOW-UP','Evidence quality','Find missing verification, unowned work and overdue target dates before acting.',button('Open alerts','nav-alerts','sm','','shield-alert'))}<div class="stats-grid">${stat('Open alerts',total,'Current workload','shield-alert')}${stat('Alerts with gaps',flagged.length,'At least one missing fact','eye','amber')}${stat('Evidence gaps',gapsCount,'Across open alerts','alert','red')}${stat('Execution blockers',blockedCount,'No automatic overrides','check','teal')}</div><div class="two-col">${panel('Quality review queue','Each issue shows the exact facts that should be investigated.',flagged.length?flagged.map(({alert:a,gaps})=>`<div class="quality-row"><span class="stat-icon amber">${I('alert',18)}</span><div class="item-main"><strong>${esc(a.packageName)} · ${esc(repoName(data,a))}</strong><div class="small muted" style="margin-top:4px">${gaps.map(g=>`• ${esc(g)}`).join(' · ')}</div></div><button class="btn sm" data-action="detail" data-id="${esc(a.id)}">Review</button></div>`).join(''):empty('check','All tracked facts are complete','No evidence gaps detected by the built-in rules. Human verification remains essential.'))}${panel('Quality rules','Used to flag incomplete records, not to invent missing information.',`<div class="help-step"><span class="step-index">1</span><div><h3>Check real advisory data</h3><p>Severity, version and advisory identifiers must come from a source you trust.</p></div></div><div class="help-step"><span class="step-index">2</span><div><h3>Prove real code usage</h3><p>Mark a package as used or unused only after recording evidence and review date.</p></div></div><div class="help-step"><span class="step-index">3</span><div><h3>Assign an owner and deadline</h3><p>Accountability is explicit. Overdue dates are highlighted, never silently changed.</p></div></div><div class="help-step"><span class="step-index">4</span><div><h3>Retain rollback and tests</h3><p>Never close as resolved without at least one passing test and documented rationale.</p></div></div>`)}</div>`;
}
const guideContent=[
 ['01','Register repositories','Create a record for each GitHub repository. You provide owner/repository and the exact HTTPS URL. This does not connect GitHub or request access tokens.'],
 ['02','Bring in trusted security signals','Register one advisory manually or import a Dependabot JSON export. Preview validates the format and excludes duplicate alert IDs before any record is saved.'],
 ['03','Triage using real evidence','Record the affected package, direct/transitive dependency path, safe version, severity and actual code usage. Unknown is a valid—and important—answer.'],
 ['04','Explain the upgrade before attempting it','Document exact npm commands, approval, compatibility impact, prerequisites, migration notes, rollback and regression tests. Plan readiness is not execution.'],
 ['05','Test and close with accountability','Record outcomes for each test. Close as Resolved only after readiness checks and at least one passing test, or use Risk accepted with a documented rationale and approver.'],
 ['06','Preserve and share outcomes','Export a JSON backup, CSV register or Markdown report. This is local-first: different browsers, devices and domains do not share state automatically.']
];
function guidePage(){
 const specs=`<div class="detail-grid">${box('Severity','Advisory-provided level. Never recalculated by Didban.')}${box('Priority score','Internal sorting aid: severity + confirmed code usage + cross-repo overlap + manual modifier.')}${box('Readiness','Documentation completeness and absence of known blockers, not proof of execution.')}${box('Final status','A human-recorded decision with evidence. No repository changes occur.')}</div>`;
 return `${head('GETTING STARTED · THE FULL WORKFLOW','A clear path from alert to verified outcome','Follow these steps once, then return anytime as you work.',button('Replay the tour','welcome','sm','','info'))}<div class="two-col">${panel('Your six-step workflow','Designed around real security engineering handoffs.',guideContent.map(([n,title,desc])=>`<div class="help-step"><span class="step-index">${n}</span><div><h3>${esc(title)}</h3><p>${esc(desc)}</p></div></div>`).join(''))}${panel('Understand the three most important concepts','Avoid treating every security metric as interchangeable.',`${specs}<div class="note warn" style="margin-top:16px">${I('info',17)} Didban does not scan repositories, execute npm, fetch secrets, patch code or validate advisories automatically.</div><div class="action-menu">${button('Create repository','repo-new','sm')}${button('Import Dependabot alerts','dependabot-open','sm','','file')}</div>`)}</div>${panel('Reference: how the score is calculated','Transparent and deterministic; based only on fields you entered.',`<div class="code-block">Severity: Critical +40  ·  High +30  ·  Moderate +20  ·  Low +10  ·  Unknown +0\nConfirmed used in source code: +25\nShared across repositories: +10 per additional repository (max +20)\nManual priority: High +12  ·  Normal +0  ·  Low −5\nFinal priority score: max(0, sum)\n\nThis is an operational heuristic, not a CVSS score.</div>`)}`;
}
function settingsPage(){
 return `${head('DATA OWNERSHIP · PORTABILITY','Settings & data','You control your records, exports, appearance and local storage. There is no server-side account.',button('Replay onboarding','welcome','sm','','info'))}<div class="two-col">${panel('Backups & exports','Export frequently and store backups securely outside your browser.',`<p class="small muted">Your local browser currently contains <strong>${fmt(data.repositories.length)}</strong> repositories, <strong>${fmt(data.alerts.length)}</strong> alerts and <strong>${fmt(data.history.length)}</strong> history entries.</p><div class="action-menu">${button('Export JSON backup','export-json','sm','','file')}${button('Export alert CSV','export-csv','sm','','file')}${button('Download Markdown report','export-markdown','sm','','file')}</div><div class="note" style="margin-top:15px">${I('info',16)} Exports include the data you entered, which may contain sensitive internal project notes. Review before sharing.</div>`)}${panel('Import an existing backup','Supports backups from the Persian Didban edition and this English edition (schema v1).',`<form id="backup-form"><label class="field-label">Backup file (.json)<input name="file" class="field" type="file" accept=".json,application/json" required></label><div class="panel-action-row"><button type="submit" class="btn">${I('file',15)} Restore from JSON</button></div></form><p class="form-tip" style="margin-top:12px">A restore replaces all records in this browser after confirmation. Back up your current state first.</p>`)}</div><div class="two-col">${panel('Quick start & appearance','Learn without relying on undocumented defaults.',`<div class="action-menu">${button('Open guide','nav-guide','sm','','info')}${button(state.theme==='dark'?'Switch to light mode':'Switch to dark mode','theme','sm','','sun')}${button('Load labeled sample data','demo','sm','','layers')}</div><div class="note" style="margin-top:15px">${I('info',16)} Sample data uses fictitious repositories and advisories. This action requires an empty workspace and never calls GitHub.</div>`)}${panel('Danger zone','This affects only data stored under the English edition’s storage key.',`<p class="small muted">Remove local records if you are resetting a browser or ending a test. The action does not affect your repositories or the Persian edition.</p><div class="action-menu">${button('Clear local workspace','clear-data','danger','','trash')}</div>`)}</div>`;
}
function timeline(alertId){const hist=data.history.filter(x=>x.alertId===alertId);return hist.length?hist.map(item=>`<div class="help-step"><span class="step-index">${I('history',16)}</span><div><h3>${esc(item.action)} <span class="muted">· ${dt(item.at)}</span></h3><p>${esc(item.detail||'No details')}</p></div></div>`).join(''):empty('history','No activity recorded','Changes appear here as you update or review this alert.');}
function detailPage(){
 const a=alertOf(data,state.selected);if(!a)return `${head('ALERT DETAILS','Alert not found','The record may have been removed.')}<div class="actions">${button('Return to alerts','nav-alerts','sm')}</div>`;
 const u=urgency(data,a),p=a.plan||{},r=readiness(a);
 const tabs=[['summary','Summary'],['plan','Remediation plan'],['tests','Test evidence'],['history','Activity']].map(([id,t])=>`<button class="${state.tab===id?'active':''}" data-action="tab" data-tab="${id}">${t}</button>`).join('');
 let content='';
 if(state.tab==='summary'){
  content=`<div class="detail-grid">${box('Repository',esc(repoName(data,a)))}${box('Dependency kind',esc(KIND[a.kind]||'Unverified'))}${box('Current version',show(a.currentVersion))}${box('Target safe version',show(a.safeVersion))}${box('Package ecosystem',esc(a.ecosystem||'npm'))}${box('Priority score',`<strong>${u.score}</strong> ${u.needsReview?pill('Needs verification','review'):''}`)}${box('Code usage',esc(USAGE[a.codeUse]||'Not investigated'))}${box('Owner / deadline',esc(a.owner||'Unassigned')+' · '+esc(a.dueDate||'No due date'))}${box('Alert ID',show(a.alertId))}${box('GitHub advisory',link(a.url,'Open source alert'))}${box('Dependency path',`<code>${show(a.depPath)}</code>`)}${box('Evidence source',link(a.sourceUrl,'Open supporting source'))}</div><div style="height:17px"></div>${panel('Evidence and decisions','Only verified facts are reliable; unknowns remain explicitly unknown.',`<div class="detail-grid">${box('Usage evidence',show(a.evidence))}${box('Last reviewed',esc(a.verifiedAt||'Not reviewed'))}${box('Source / provenance',show(a.provenance))}${box('Execution blocker',show(a.blocker))}${box('Notes',show(a.notes))}${box('Priority breakdown',`Severity ${u.components.severity} + usage ${u.components.use} + cross-repo ${u.components.shared} + override ${u.components.manual}`)}</div>`)}<div class="action-menu">${button('Edit alert information','alert-edit','sm',a.id,'edit')}${button('Plan remediation','plan-edit','sm',a.id,'list-ordered')}</div>`;
 }else if(state.tab==='plan'){
  content=`<div class="triage-banner"><div><div class="triage-label">REMEDIATION READINESS</div><h2 class="triage-title">${r.ready?'Prerequisites documented':'Plan needs more information'}</h2><p class="triage-desc">${r.ready?'This is eligible for the manual execution queue. No commands have been run by Didban.':r.reasons.join(' · ')}</p></div>${pill(r.ready?'Ready':'Incomplete',r.ready?'ready':'review')}</div><div class="detail-grid">${box('Compatibility risk',esc(RISK[p.compatRisk]||RISK.unknown))}${box('Approved by',show(p.approvedBy))}${box('Execution order',p.executionOrder||a.executionOrder||'Automatic')}${box('Command approval',pill(p.commandsApproved?'Approved':'Not approved',p.commandsApproved?'ready':'review'))}</div><div style="height:17px"></div>${panel('Upgrade commands','Copy and run externally only after human review. This site NEVER executes npm.',`<pre class="code-block">${esc(p.commands||'# No commands documented yet')}</pre>${p.commands?`<div class="action-menu">${button('Copy exact commands','copy-commands','sm',a.id,'file')}</div>`:''}`)}<div style="height:17px"></div>${panel('Risk, migration & rollback','Keep recovery steps explicit before implementation.',`<div class="detail-grid">${box('Compatibility assessment',show(p.compatNotes))}${box('Prerequisites',show(p.prerequisites))}${box('Migration procedure',show(p.migrationSteps))}${box('Rollback plan',show(p.rollback))}</div>`)}<div class="action-menu">${button('Edit remediation plan','plan-edit','primary',a.id,'edit')}${button('Review tests','detail-tests','sm',a.id,'check')}</div>`;
 }else if(state.tab==='tests'){
  const tests=p.tests||[];content=`<div class="note" style="margin-bottom:16px">${I('info',17)} Test outcomes are recorded manually. A Resolved closure requires at least one Passed test and a complete, unblocked plan.</div>${panel('Regression & verification checks',`${tests.length} documented tests`,tests.length?tests.map(t=>`<div class="test-item"><div class="item-main"><strong>${esc(t.label)}</strong><div class="item-sub">${dt(t.at)} ${t.notes?' · '+esc(t.notes):''}</div></div><div class="test-controls">${pill(OUTCOME[t.status]||'Not run',t.status)}<button class="btn sm" data-action="test-edit" data-id="${esc(a.id)}" data-test="${esc(t.id)}">Record result</button></div></div>`).join(''):empty('check','No test checklist yet','Add realistic unit, integration, smoke and rollback checks in the remediation plan.',button('Edit plan','plan-edit','sm',a.id,'edit')))}<div class="action-menu">${button('Edit test checklist','plan-edit','sm',a.id,'edit')}</div>`;
 }else{content=panel('Recorded activity','Local, human-readable history; it is not an immutable server-side audit log.',timeline(a.id));}
 const statusSelect=`<select class="status-select" data-field="alert-status" aria-label="Alert status">${Object.entries(STATUS).map(([key,v])=>`<option value="${key}" ${a.status===key?'selected':''}>${esc(v)}</option>`).join('')}</select>`;
 return `${head('ALERT WORKSPACE',a.packageName,`${repoName(data,a)} · ${a.alertId||'Unnumbered alert'}`,`${button('Back to alerts','nav-alerts','sm','','arrow')}${button('Edit alert','alert-edit','sm',a.id,'edit')}`)}<section class="panel" style="margin-bottom:17px"><div class="panel-body"><div class="kpi-section" style="gap:16px;flex-wrap:wrap"><div class="tagline">${severityBadge(a)}${statusBadge(a)}${pill('Priority '+u.score,'new')}${pill(r.ready?'Plan ready':'Plan incomplete',r.ready?'ready':'review')}</div><label class="field-label" style="margin:0">Workflow status ${statusSelect}</label></div></div></section><nav class="tabs" aria-label="Alert sections">${tabs}</nav>${content}`;
}
function field(label,name,value='',attrs='',type='text',extra=''){
 return `<label class="field-label ${extra}">${esc(label)}<input class="field" type="${type}" name="${esc(name)}" value="${esc(value)}" ${attrs}></label>`;
}
function area(label,name,value='',placeholder='',extra='span2',rows=3){return `<label class="field-label ${extra}">${esc(label)}<textarea class="field" name="${esc(name)}" rows="${rows}" placeholder="${esc(placeholder)}">${esc(value)}</textarea></label>`;}
function selectField(label,name,map,value,extra=''){
 return `<label class="field-label ${extra}">${esc(label)}<select name="${esc(name)}" class="field">${Object.entries(map).map(([key,val])=>`<option value="${esc(key)}" ${key===value?'selected':''}>${esc(val)}</option>`).join('')}</select></label>`;
}
function modalShell(title,sub,contents,actions='',narrow=false){
 return `<div class="modal-backdrop-new" data-action="modal-backdrop"><section class="dialog-new ${narrow?'dialog-narrow':''}" role="dialog" aria-modal="true" aria-labelledby="dialog-title"><div class="dialog-heading"><div><h2 id="dialog-title">${esc(title)}</h2><p>${esc(sub)}</p></div><button type="button" class="icon-btn" data-action="modal-close" aria-label="Close dialog">✕</button></div>${contents}${actions?`<div class="dialog-actions">${actions}</div>`:''}</section></div>`;
}
function modalView(){const id=state.modalId;
 switch(state.modal){
  case 'repo':{
   const r=repoOf(data,id)||{};
   return modalShell(id?'Edit repository':'Add a repository','References only: GitHub credentials are never requested.',`<form id="repo-form"><div class="dialog-body"><div class="form-grid">${field('Repository slug · owner/repository','slug',r.slug||'','required placeholder="owner/repository"')}${field('Display name (optional)','alias',r.alias||'','placeholder="Customer Portal"')}${field('Exact HTTPS GitHub repository URL','url',r.url||'','required placeholder="https://github.com/owner/repository"','url','span2')}${selectField('Environment','environment',{'':'Not specified',production:'Production',staging:'Staging',development:'Development',other:'Other'},r.environment||'')}${area('Context / notes','notes',r.notes||'','Optional context for colleagues or future review')}</div></div><div class="dialog-actions"><button class="btn" type="button" data-action="modal-close">Cancel</button><button class="btn primary" type="submit">${I('check',15)} ${id?'Save changes':'Add repository'}</button></div></form>`);
  }
  case 'alert':{
   const a=alertOf(data,id)||{};
   const repositories=Object.fromEntries(data.repositories.map(r=>[r.id,r.alias||r.slug]));
   const fieldGroup=`<div class="form-section-title">01 / Source and identification</div>${selectField('Repository','repositoryId',repositories,a.repositoryId||state.modalTest||Object.keys(repositories)[0])}${field('npm package name','packageName',a.packageName||'','required placeholder="@scope/package or lodash"')}${field('Dependabot alert number / ID','alertId',a.alertId||'','placeholder="123"')}${field('GitHub alert URL','url',a.url||'','placeholder="https://github.com/owner/repo/security/dependabot/1"','url')}${selectField('Severity from source','severity',SEVERITY,a.severity||'unknown')}${selectField('Dependency kind','kind',KIND,a.kind||'unknown')}${field('Current / affected version','currentVersion',a.currentVersion||'','placeholder="e.g. 1.2.0"')}${field('First verified safe version','safeVersion',a.safeVersion||'','placeholder="Do not guess"')}
 <div class="form-section-title">02 / Evidence and scope</div>${selectField('Actual code usage','codeUse',USAGE,a.codeUse||'unknown')}${field('Evidence review date','verifiedAt',a.verifiedAt||'','','date')}${area('Usage evidence · required if marking used or unused','evidence',a.evidence||'','Concrete code references, trace, grep result, reviewer…')}${area('Direct/transitive dependency path','depPath',a.depPath||'','e.g. app > framework > package')}${field('Advisory or evidence source URL','sourceUrl',a.sourceUrl||'','Optional HTTPS link','url')}${field('Source provenance','provenance',a.provenance||'','e.g. GitHub Dependabot, manual review')}
 <div class="form-section-title">03 / Ownership and decision</div>${selectField('Workflow status','status',Object.fromEntries(Object.entries(STATUS).filter(([k])=>id||!['resolved','accepted'].includes(k))),a.status||'new')}${selectField('Manual priority adjustment','manualPriority',{normal:'Normal · no change',high:'Elevated · +12',low:'Lowered · −5'},a.manualPriority||'normal')}${field('Assigned owner','owner',a.owner||'','placeholder="Owner name or team"')}${field('Target date','dueDate',a.dueDate||'','','date')}${area('Current blocker','blocker',a.blocker||'','Issue preventing progress, if any')}${area('Additional notes','notes',a.notes||'','Facts, assumptions, decisions and links')}`;
   return modalShell(id?'Edit security alert':'Record a security alert','Do not infer version, severity or exploitability from incomplete evidence.',`<form id="alert-form"><div class="dialog-body"><div class="form-grid">${fieldGroup}</div></div><div class="dialog-actions"><button class="btn" type="button" data-action="modal-close">Cancel</button><button class="btn primary" type="submit">${I('check',15)} ${id?'Save alert':'Record alert'}</button></div></form>`);
  }
  case 'plan':{
   const a=alertOf(data,id),p=a?.plan||{};
   if(!a)return '';
   return modalShell('Build a remediation plan',`For ${a.packageName} · ${repoName(data,a)}. All commands remain manual.`,`<form id="plan-form"><div class="dialog-body"><div class="form-grid"><div class="form-section-title">01 / Exact commands and authorization</div>${area('Upgrade commands · reviewed npm commands only','commands',p.commands||'','e.g. npm install package@verified-safe-version','span2',4)}<label class="field-label"><span>Command approval</span><span class="card-subtle" style="font-weight:500"><input name="commandsApproved" type="checkbox" ${p.commandsApproved?'checked':''}> Commands reviewed by a human</span></label>${field('Approved by','approvedBy',p.approvedBy||'','placeholder="Reviewer name"')}<div class="form-section-title">02 / Change impact and rollout</div>${selectField('Compatibility risk','compatRisk',RISK,p.compatRisk||'unknown')}${field('Manual execution order (optional)','executionOrder',a.executionOrder||'','min="1" placeholder="1"','number')}${area('Compatibility risk assessment','compatNotes',p.compatNotes||'','Breaking changes, APIs, build tools, transitive dependencies')}${area('Prerequisites','prerequisites',p.prerequisites||'','Backups, dependency lockfile, staging, feature flags')}${area('Migration and rollout steps','migrationSteps',p.migrationSteps||'','What should happen, in what order?')}${area('Rollback / recovery steps · required for readiness','rollback',p.rollback||'','Exact restore or rollback commands, checks and ownership')}
 <div class="form-section-title">03 / Regression and acceptance checks</div>${area('Test checklist · one test per line','tests',(p.tests||[]).map(x=>x.label).join('\n'),'Unit tests\nBuild\nCritical user flows\nRollback verification','span2',5)}<p class="form-tip span2">Saving preserves existing outcomes for identical checklist labels. Editing a label creates a new untested check.</p></div></div><div class="dialog-actions"><button class="btn" type="button" data-action="modal-close">Cancel</button><button class="btn primary" type="submit">${I('check',15)} Save plan</button></div></form>`);
  }
  case 'test':{
   const a=alertOf(data,id),t=a?.plan?.tests?.find(x=>x.id===state.modalTest);
   if(!t)return '';
   return modalShell('Record test evidence',`${a.packageName} · ${t.label}`,`<form id="test-form"><div class="dialog-body">${selectField('Verified outcome','status',OUTCOME,t.status||'pending')}${area('Evidence / outcome notes','notes',t.notes||'','Build logs, test run ID, observed results, reviewer', '',4)}</div><div class="dialog-actions"><button class="btn" type="button" data-action="modal-close">Cancel</button><button class="btn primary" type="submit">Record outcome</button></div></form>`, '',true);
  }
  case 'closure':{
   const a=alertOf(data,id);
   if(!a)return '';
   const name=state.modalMethod==='resolved'?'Resolve alert':'Accept recorded risk';
   return modalShell(name,'A documented decision is required. This does not change GitHub alert status.',`<form id="closure-form"><div class="dialog-body"><div class="note warn" style="margin-bottom:18px">${I('info',17)} ${state.modalMethod==='resolved'?'Resolution requires plan readiness and at least one passed test.':'Risk acceptance requires a reason and human approval. It does not mean the vulnerability is fixed.'}</div>${field('Reviewed / approved by','reviewer','','required placeholder="Name or team"')}${area('Closure rationale and evidence','reason','','Reference PR, test run, approval ticket or explicit business exception','','5')}<label class="field-label">Confirmation <span class="card-subtle"><input required type="checkbox" name="confirm"> I understand this is a local record only.</span></label></div><div class="dialog-actions"><button class="btn" type="button" data-action="modal-close">Cancel</button><button class="btn primary" type="submit">${I('check',15)} Confirm ${state.modalMethod==='resolved'?'resolution':'risk acceptance'}</button></div></form>`, '',true);
  }
  case 'welcome':{
   const steps=[['Know what Didban does','A deliberate workspace for collecting true evidence, prioritizing alerts and documenting remediation. It never scans, patches, deploys or executes automatically.'],['Follow a defensible sequence','Register a repository → record advisories → verify code usage → prepare commands, rollback and regression checks → review and close.'],['Distinguish three independent signals','Severity is the advisory level. Priority is an internal sorting score. Readiness is the completeness of prerequisites—not execution or proof of safety.'],['Own your data and decisions','Records stay in browser storage. Export backups regularly. GitHub alert and npm changes must be performed separately by an authorized engineer.']];
   const [title,desc]=steps[state.onboardStep];
   return modalShell('Welcome to Didban Security','A quick, four-step orientation before you begin.',`<div class="dialog-body"><div class="eyebrow">STEP ${state.onboardStep+1} OF 4</div><div class="hero" style="margin:10px 0 19px;min-height:0;display:block"><div class="hero-kicker">DEPENDENCY RISK OPERATIONS</div><h2>${esc(title)}</h2><p>${esc(desc)}</p></div><div class="onboard-steps">${steps.map((_,i)=>`<div class="onboard-step" style="opacity:${i<=state.onboardStep?1:.42}"><div class="step-num">${i+1}</div><strong>${i<state.onboardStep?'Completed':i===state.onboardStep?'Current':'Next'}</strong></div>`).join('')}</div></div><div class="dialog-actions">${button('Skip tour','welcome-done','sm','','arrow')}<button class="btn" data-action="welcome-back" ${state.onboardStep===0?'disabled':''}>Back</button>${button(state.onboardStep===3?'Start using Didban':'Continue','welcome-next')}</div>`,'',true);
  }
  case 'import':{
   if(!data.repositories.length)return modalShell('Import Dependabot alerts','Register a repository before importing.',`<div class="dialog-body">${empty('layers','No repository available','A target repository is needed to associate imported alerts.')}</div><div class="dialog-actions">${button('Register repository','repo-new')}</div>`, '',true);
   return modalShell('Import GitHub Dependabot JSON','Read-only import · npm alerts · duplicates and invalid rows are skipped.',`<form id="dependabot-form"><div class="dialog-body"><div class="form-grid">${selectField('Destination repository','repositoryId',Object.fromEntries(data.repositories.map(r=>[r.id,r.slug])),data.repositories[0].id,'span2')}<label class="field-label span2">JSON file<input type="file" name="file" accept=".json,application/json" class="field" required></label></div><div class="note" style="margin-top:10px">${I('info',17)} Export with GitHub CLI: <code>gh api --paginate --jq '.[]' repos/OWNER/REPO/dependabot/alerts | jq -s '.'</code>. Requires jq; outputs a single valid JSON array across all pages. Only supported records appear in the preview; nothing is saved until confirmation.</div></div><div class="dialog-actions"><button class="btn" type="button" data-action="modal-close">Cancel</button><button class="btn primary" type="submit">Preview import</button></div></form>`);
  }
  case 'import-preview':{
   const p=state.staged; if(!p)return '';
   const examples=p.rows.slice(0,10).map(x=>`<div class="row-item"><span class="stat-icon ${x.ok?'teal':'amber'}">${I(x.ok?'check':'alert',16)}</span><div class="item-main"><strong>${x.ok?esc(x.alert.packageName):'Skipped row '+x.index}</strong><div class="item-sub">${x.ok?esc(x.alert.alertId):esc(x.reason)}</div></div>${pill(x.ok?'Valid':'Skipped',x.ok?'ready':'review')}</div>`).join('');
   return modalShell('Review import preview','Only valid, non-duplicate records will be saved.',`<div class="dialog-body"><div class="stats-grid" style="grid-template-columns:repeat(3,1fr)">${stat('Total rows',p.rows.length,'Reviewed','file')}${stat('Importable',p.valid.length,'New alerts','check','teal')}${stat('Skipped',p.skipped.length,'Invalid or duplicate','alert','amber')}</div><div class="card-subtle">${examples}</div><p class="form-tip">Showing the first ${Math.min(10,p.rows.length)} of ${p.rows.length}. Existing records are never overwritten.</p></div><div class="dialog-actions">${button('Back to file selection','import-back','sm','','arrow')}${button(`Import ${p.valid.length} alerts`,'import-commit')}</div>`);
  }
  case 'palette':{
   const entries=[...pages.map(([key,ico,label])=>({type:'page',id:key,label,sub:'Page',ico})),...data.alerts.map(a=>({type:'alert',id:a.id,label:a.packageName,sub:repoName(data,a)+' · '+(a.alertId||'No ID'),ico:'shield-alert'}))];
   const q=state.commandQuery.trim().toLowerCase();const found=entries.filter(x=>[x.label,x.sub].some(v=>v.toLowerCase().includes(q))).slice(0,14);
   return modalShell('Search Didban','Jump to pages or a tracked alert · Ctrl/⌘ + K',`<div class="dialog-body"><input id="command-search" class="field" autocomplete="off" autofocus placeholder="Type a page, package or alert ID…" value="${esc(state.commandQuery)}" style="width:100%"><div id="command-results" style="margin-top:13px">${paletteRows(found)}</div></div>`, '',true);
  }
  default:return '';
 }
}
function paletteRows(rows){return rows.length?rows.map(x=>`<button class="quick-action" style="width:100%" data-action="${x.type==='page'?'nav':'detail'}" ${x.type==='page'?`data-page="${esc(x.id)}"`:`data-id="${esc(x.id)}"`}><span class="quick-action-ico">${I(x.ico,18)}</span><span class="item-main"><strong>${esc(x.label)}</strong><small>${esc(x.sub)}</small></span>${I('arrow',15)}</button>`).join(''):empty('search','Nothing found','Try a different package or page name.');}
function formData(form){return Object.fromEntries([...new FormData(form)].map(([k,v])=>[k,typeof v==='string'?v.trim():v]));}
function editHistory(old,next){return Object.keys(next).filter(k=>JSON.stringify(old?.[k]??'')!==JSON.stringify(next[k]??'')).filter(k=>!['updatedAt','createdAt','id'].includes(k)).slice(0,20).join(', ')||'No material changes';}
function saveRepo(form){
 const v=formData(form),old=repoOf(data,state.modalId),err=validateRepo(data,v,old?.id);
 if(err)return toast(err,true);
 const obj={...v,id:old?.id||uid(),createdAt:old?.createdAt||now()};
 if(old){data.repositories=data.repositories.map(r=>r.id===old.id?obj:r);log(null,'Repository updated',obj.slug+' · '+editHistory(old,obj));}
 else{data.repositories.push(obj);log(null,'Repository registered',obj.slug);}
 persist();state.modal='';render();toast(old?'Repository updated.':'Repository registered.');
}
function saveAlert(form){
 const v=formData(form),old=alertOf(data,state.modalId),err=validateAlert(data,v,old?.id);
 if(err)return toast(err,true);
 if(['resolved','accepted'].includes(v.status)&&!['resolved','accepted'].includes(old?.status))return toast('Use the documented closure flow from the alert detail page.',true);
 const obj={...v,id:old?.id||uid(),ecosystem:'npm',plan:old?.plan||{commands:'',commandsApproved:false,compatRisk:'unknown',rollback:'',tests:[]},closure:['resolved','accepted'].includes(v.status)?old?.closure||null:null,executionOrder:old?.executionOrder??null,createdAt:old?.createdAt||now(),updatedAt:now()};
 if(old){data.alerts=data.alerts.map(a=>a.id===old.id?obj:a);log(obj.id,'Alert updated','Edited fields: '+editHistory(old,obj));}
 else{data.alerts.push(obj);log(obj.id,'Alert created',obj.packageName+' in '+repoName(data,obj));}
 persist();state.modal='';state.page='detail';state.selected=obj.id;state.tab='summary';render();toast(old?'Alert updated.':'Alert created.');
}
function savePlan(form){
 const a=alertOf(data,state.modalId);if(!a)return;
 const v=formData(form),approved=form.elements.namedItem('commandsApproved')?.checked||false,err=validatePlan(v,approved);
 if(err)return toast(err,true);
 const original=a.plan||{};
 const names=[...new Set(String(v.tests||'').split('\n').map(x=>x.trim()).filter(Boolean))];
 const tests=names.map(label=>(original.tests||[]).find(t=>t.label===label)||{id:uid(),label,status:'pending',notes:'',at:null});
 const next={commands:v.commands||'',commandsApproved:approved,approvedBy:approved?v.approvedBy:'',compatRisk:v.compatRisk||'unknown',compatNotes:v.compatNotes||'',prerequisites:v.prerequisites||'',migrationSteps:v.migrationSteps||'',rollback:v.rollback||'',tests};
 a.plan=next;a.executionOrder=v.executionOrder?Number(v.executionOrder):null;a.updatedAt=now();
 log(a.id,'Remediation plan updated','Updated: '+editHistory(original,next));persist();state.modal='';state.page='detail';state.selected=a.id;state.tab='plan';render();toast('Plan recorded. No commands were executed.');
}
function saveTest(form){const a=alertOf(data,state.modalId),t=a?.plan?.tests?.find(t=>t.id===state.modalTest);if(!t)return;const v=formData(form);if(!OUTCOME[v.status])return toast('Invalid test outcome.',true);if(t.status!==v.status||t.notes!==v.notes){log(a.id,'Test outcome recorded',`${t.label}: ${OUTCOME[t.status]} → ${OUTCOME[v.status]}`);t.status=v.status;t.notes=v.notes;t.at=now();a.updatedAt=now();persist();}state.modal='';state.page='detail';state.tab='tests';render();toast('Manual test outcome saved.');}
function saveClosure(form){
 const a=alertOf(data,state.modalId),v=formData(form),method=state.modalMethod;
 if(!a||!['resolved','accepted'].includes(method))return;
 const err=validateClosure(a,method,v.reviewer,v.reason);if(err)return toast(err,true);
 const prior=a.status;a.status=method;a.closure={method,reviewer:v.reviewer,reason:v.reason,at:now()};a.updatedAt=now();
 log(a.id,method==='resolved'?'Alert resolved':'Risk accepted',`Previous state: ${STATUS[prior]} · Reviewed by ${v.reviewer} · ${v.reason.slice(0,240)}`);
 persist();state.modal='';render();toast(method==='resolved'?'Resolution recorded. GitHub was not modified.':'Risk acceptance recorded. GitHub was not modified.');
}
function download(name,text,mime){const file=new Blob([text],{type:mime}),url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportJSON(){download('didban-security-backup.json',JSON.stringify({...data,exportedAt:now()},null,2),'application/json;charset=utf-8');toast('JSON backup downloaded.');}
function exportCSV(){const columns=[['repository','Repository'],['alertId','Alert ID'],['packageName','Package'],['ecosystem','Ecosystem'],['severity','Severity'],['kind','Dependency kind'],['currentVersion','Current version'],['safeVersion','Safe version'],['codeUse','Code usage'],['status','Status'],['owner','Owner'],['dueDate','Target date'],['depPath','Dependency path'],['priority','Priority score'],['blocked','Blocked'],['url','GitHub alert URL']];
 const rows=[columns.map(c=>csvCell(c[1])).join(',')];for(const a of data.alerts){const v={...a,repository:repoName(data,a),priority:urgency(data,a).score,blocked:blocked(a)?'Yes':'No'};rows.push(columns.map(([key])=>csvCell(v[key])).join(','));}
 download('didban-security-alert-register.csv','\ufeff'+rows.join('\r\n'),'text/csv;charset=utf-8');toast('CSV report downloaded.');}
function exportMarkdown(){
 const open=active(data),r=roadmap(data);let lines=['# Didban Security — Dependency Risk Report','',`Generated: ${now()}`,'','> This report reflects manually entered local records. It is not a GitHub scan or a verification of completed upgrades.','',`- Repositories: ${data.repositories.length}`,`- Open alerts: ${open.length}`,`- Ready for manual execution: ${r.ready.length}`,`- Blocked: ${r.blocked.length}`,`- Closed: ${r.closed.length}`,'','## Tracked alerts',''];
 if(!data.alerts.length)lines.push('_No alerts recorded._');
 for(const a of [...data.alerts].sort((a,b)=>urgency(data,b).score-urgency(data,a).score)){
  const p=a.plan||{},ready=readiness(a);
  lines.push(`### ${a.packageName.replace(/[\r\n#]/g,' ')} · ${repoName(data,a)}`,'',`- Alert ID: ${a.alertId||'Not recorded'}`,`- Severity: ${SEVERITY[a.severity]||'Unverified'}`,`- Status: ${STATUS[a.status]||'Unknown'}`,`- Priority: ${urgency(data,a).score}`,`- Safe version: ${a.safeVersion||'Not verified'}`,`- Code usage: ${USAGE[a.codeUse]||USAGE.unknown}`,`- Owner: ${a.owner||'Unassigned'}`,`- Readiness: ${ready.ready?'Ready for manual action':ready.reasons.join('; ')}`,`- GitHub URL: ${validGithubUrl(a.url)?a.url:'Not provided'}`,'',`**Upgrade commands:**`, '```sh',String(p.commands||'# Not documented').replace(/```/g,'` ` `'),'```','',`**Rollback:** ${p.rollback||'Not documented'}`,'',`**Checks:**`,...(p.tests||[]).map(t=>`- [${t.status==='pass'?'x':' '}] ${t.label} — ${OUTCOME[t.status]||'Not run'}`),'');
 }
 lines.push('','## Limitations','','- No automated GitHub API calls or repository modifications.','- Human-entered status and tests are not externally verified.','- Local browser history is editable and is not an immutable audit system.');
 download('didban-security-report.md',lines.join('\n'),'text/markdown;charset=utf-8');toast('Markdown report downloaded.');
}
async function readJSON(file){if(!file||file.size>5*1024*1024)throw Error('Select a JSON file under 5 MB.');return JSON.parse(await file.text());}
async function restoreBackup(file){try{const obj=validateBackup(await readJSON(file));if(!confirm(`Restore ${obj.repositories.length} repositories and ${obj.alerts.length} alerts? This replaces all English-edition records stored in this browser.`))return;data=obj;persist();state.modal='';navigate('overview');toast('Backup restored successfully.');}catch(e){toast('Backup import failed: '+e.message,true);}}
async function previewImport(file,repoId){try{
 const raw=await readJSON(file);
 if(!repoOf(data,repoId))throw Error('Select a valid repository.');
 const normalized=normalizeDependabot(raw,repoId),preview=importPreview(data,normalized,repoId);
 state.staged={...preview,repoId};state.modal='import-preview';render();
 }catch(e){toast('Cannot preview import: '+e.message,true);}}
function commitImport(){const p=state.staged;if(!p)return;for(const v of p.valid){const a={...v.alert,id:uid(),createdAt:now(),updatedAt:now(),executionOrder:null};data.alerts.push(a);log(a.id,'Imported Dependabot advisory',`${a.packageName} · ${a.alertId} · ${repoName(data,a)}`);}const added=p.valid.length;persist();state.staged=null;state.modal='';navigate('alerts');toast(`${added} advisories imported. ${p.skipped.length} skipped. No GitHub changes made.`);}
function moveReady(id,delta){const ready=roadmap(data).ready,i=ready.findIndex(a=>a.id===id),j=i+delta;if(i<0||j<0||j>=ready.length)return;[ready[i],ready[j]]=[ready[j],ready[i]];ready.forEach((a,k)=>{if(a.executionOrder!==k+1){a.executionOrder=k+1;a.updatedAt=now();log(a.id,'Execution order updated',`Manual order: ${k+1}`);}});persist();render();}
function handleAction(el){const action=el.dataset.action,id=el.dataset.id||'';
 switch(action){
  case 'nav':navigate(el.dataset.page);break;
  case 'nav-alerts':navigate('alerts');break;case 'nav-roadmap':navigate('roadmap');break;case 'nav-guide':navigate('guide');break;case 'nav-insights':navigate('insights');break;case 'nav-settings':navigate('settings');break;
  case 'detail':navigate('detail',id);break;
  case 'detail-tests':state.page='detail';state.selected=id;state.tab='tests';state.modal='';render();break;
  case 'tab':state.tab=el.dataset.tab;render();break;
  case 'new-alert':if(data.repositories.length)modal('alert','',id);else {toast('Register a repository before adding an alert.',true);modal('repo');}break;
  case 'alert-edit':modal('alert',id);break;
  case 'repo-new':modal('repo');break;case 'repo-edit':modal('repo',id);break;
  case 'repo-remove':{const r=repoOf(data,id);if(!r)return;const related=data.alerts.filter(a=>a.repositoryId===id).length;if(related){toast(`This repository has ${related} tracked alert(s). Delete or migrate them before removal.`,true);break;}if(!confirm(`Remove ${r.slug} from this local workspace?`))break;data.repositories=data.repositories.filter(x=>x.id!==id);log(null,'Repository removed',r.slug);persist();render();toast('Repository removed locally.');break;}
  case 'plan-edit':modal('plan',id);break;case 'test-edit':modal('test',id,el.dataset.test);break;
  case 'alert-status':break;
  case 'modal-close':state.modal='';state.staged=null;render();break;
  case 'theme':state.theme=state.theme==='light'?'dark':'light';localStorage.setItem(THEME_KEY,state.theme);render();break;
  case 'drawer':state.drawer=true;render();break;case 'drawer-close':state.drawer=false;render();break;
  case 'quick':state.filters.quick=el.dataset.value;render();break;
  case 'filters-reset':state.filters={q:'',severity:'',status:'',repositoryId:'',codeUse:'',sort:'urgency',quick:'all'};render();break;
  case 'palette':state.commandQuery='';modal('palette');break;
  case 'copy-commands':{const a=alertOf(data,id);const cmd=a?.plan?.commands;if(cmd)navigator.clipboard?.writeText(cmd).then(()=>toast('Exact commands copied. Review before using outside Didban.'),()=>toast('Clipboard permission not available.',true));break;}
  case 'move-up':moveReady(id,-1);break;case 'move-down':moveReady(id,1);break;
  case 'dependabot-open':if(data.repositories.length)modal('import');else {toast('Register a destination repository first.',true);modal('repo');}break;
  case 'import-back':state.staged=null;modal('import');break;case 'import-commit':commitImport();break;
  case 'welcome':state.onboardStep=0;modal('welcome');break;
  case 'welcome-back':state.onboardStep=Math.max(0,state.onboardStep-1);render();break;
  case 'welcome-next':if(state.onboardStep>=3){localStorage.setItem(ONBOARD_KEY,'done');state.modal='';navigate('guide');}else{state.onboardStep++;render();}break;
  case 'welcome-done':localStorage.setItem(ONBOARD_KEY,'done');state.modal='';render();break;
  case 'export-json':exportJSON();break;case 'export-csv':exportCSV();break;case 'export-markdown':exportMarkdown();break;
  case 'demo':if(data.repositories.length||data.alerts.length){toast('Sample data can only be loaded into an empty workspace.',true);break;}if(!confirm('Load three clearly labeled, fictional demo alerts?'))break;data=demoDataset();persist();navigate('overview');toast('Fictional sample data loaded. This is not a GitHub scan.');break;
  case 'clear-data':if(!confirm('Delete ALL English-edition records stored in this browser? This cannot be undone without a JSON backup.'))break;data=blank();persist();navigate('overview');toast('English workspace cleared.');break;
 }
}
// Event delegation keeps re-rendering simple and avoids attaching duplicate listeners.
document.addEventListener('click',e=>{if(e.target.closest('a'))return;const el=e.target.closest('[data-action]');if(!el)return;const action=el.dataset.action;if(action==='modal-backdrop'){if(e.target===el){state.modal='';render();}return;}handleAction(el);});
document.addEventListener('change',e=>{
 const el=e.target;
 if(el.dataset.filter){state.filters[el.dataset.filter]=el.value;render();return;}
 if(el.dataset.field==='alert-status'){
  const a=alertOf(data,state.selected);if(!a||!STATUS[el.value])return;
  const next=el.value;
  if(next===a.status)return;
  if(['resolved','accepted'].includes(next)&&!['resolved','accepted'].includes(a.status)){modal('closure',a.id,'',next);return;}
  const before=a.status;
  if(['resolved','accepted'].includes(before)&&!['resolved','accepted'].includes(next))a.closure=null;
  a.status=next;a.updatedAt=now();log(a.id,'Workflow status updated',`${STATUS[before]} → ${STATUS[next]}`);persist();render();toast('Workflow status updated locally.');
 }
});
let searchDelay;
document.addEventListener('input',e=>{
 const el=e.target;
 if(el.id==='command-search'){state.commandQuery=el.value;const p=document.getElementById('command-results');if(p){const q=state.commandQuery.trim().toLowerCase();const rows=[...pages.map(([id,ico,label])=>({type:'page',id,label,sub:'Page',ico})),...data.alerts.map(a=>({type:'alert',id:a.id,label:a.packageName,sub:repoName(data,a)+' · '+(a.alertId||'No ID'),ico:'shield-alert'}))].filter(x=>(x.label+' '+x.sub).toLowerCase().includes(q)).slice(0,14);p.innerHTML=paletteRows(rows);}return;}
 if(el.id==='search-alerts'){clearTimeout(searchDelay);const q=el.value;searchDelay=setTimeout(()=>{state.filters.q=q;render();const inp=document.getElementById('search-alerts');if(inp){inp.focus();inp.setSelectionRange(q.length,q.length);}},200);}
});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!['repo-form','alert-form','plan-form','test-form','closure-form','dependabot-form','backup-form'].includes(form.id))return;e.preventDefault();
 try{if(form.id==='repo-form')saveRepo(form);else if(form.id==='alert-form')saveAlert(form);else if(form.id==='plan-form')savePlan(form);else if(form.id==='test-form')saveTest(form);else if(form.id==='closure-form')saveClosure(form);else if(form.id==='backup-form')await restoreBackup(form.elements.namedItem('file')?.files?.[0]);else if(form.id==='dependabot-form')await previewImport(form.elements.namedItem('file')?.files?.[0],form.elements.namedItem('repositoryId')?.value);}catch(err){toast('Unable to save: '+err.message,true);console.error(err);}
});
document.addEventListener('keydown',e=>{
 if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.commandQuery='';modal('palette');}
 if(e.key==='Escape'&&(state.modal||state.drawer)){state.modal='';state.drawer=false;state.staged=null;render();}
 if((e.key==='Enter'||e.key===' ')&&e.target.matches('tr[data-action="detail"]')){e.preventDefault();navigate('detail',e.target.dataset.id);}
});
if(!localStorage.getItem(ONBOARD_KEY)&&!data.repositories.length&&!data.alerts.length){state.modal='welcome';}
render();
